# Exercises exponentiation with the ** operator and pow() for non-negative
# integer exponents.
print(2 ** 10)
print(2 ** 0)
print(0 ** 0)
print(3 ** 4)
print(pow(2, 10))
print(pow(5, 0))
print(pow(2, 3) + pow(3, 2))
print(10 ** 2 ** 2)
